const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

const typeDefs = gql`
  type Document {
    id: ID!
    tenantId: String!
    filename: String!
    content: String
  }

  type Query {
    documents(tenantId: String!): [Document]
    exportDocuments(tenantId: String!, format: String): String
  }

  type Mutation {
    importDocuments(tenantId: String!, data: String!): Boolean
  }
`;

const resolvers = {
  Query: {
    documents: async (_, { tenantId }, context) => {
      const client = await pool.connect();
      try {
        // Set tenant context for RLS
        await client.query(`SET app.current_tenant = '${tenantId}'`);
        const result = await client.query(
          'SELECT id, tenant_id, filename, content FROM documents'
        );
        return result.rows.map(r => ({
          id: r.id,
          tenantId: r.tenant_id,
          filename: r.filename,
          content: r.content
        }));
      } finally {
        client.release();
      }
    },

    exportDocuments: async (_, { tenantId, format }, context) => {
      const client = await pool.connect();
      try {
        await client.query(`SET app.current_tenant = '${tenantId}'`);
        const result = await client.query(
          'SELECT id, tenant_id, filename, content FROM documents'
        );

        // Create temporary file for export - VULNERABILITY: predictable path, no exclusive flag
        const tmpFile = path.join(os.tmpdir(), `export_${tenantId}_${Date.now()}`);
        const data = JSON.stringify(result.rows);

        // Race condition: attacker can create symlink at predictable path
        fs.writeFileSync(tmpFile, data, { mode: 0o644 });

        const content = fs.readFileSync(tmpFile, 'utf8');
        // Cleanup attempt (but damage already done if symlink was followed)
        fs.unlinkSync(tmpFile);

        return content;
      } finally {
        client.release();
      }
    }
  },

  Mutation: {
    importDocuments: async (_, { tenantId, data }, context) => {
      const client = await pool.connect();
      try {
        // Write uploaded data to temp file for processing
        const tmpFile = path.join(os.tmpdir(), `import_${tenantId}_${process.pid}`);
        fs.writeFileSync(tmpFile, data, { mode: 0o666 });

        const parsed = JSON.parse(fs.readFileSync(tmpFile, 'utf8'));

        await client.query(`SET app.current_tenant = '${tenantId}'`);

        for (const doc of parsed) {
          await client.query(
            'INSERT INTO documents (tenant_id, filename, content) VALUES ($1, $2, $3)',
            [tenantId, doc.filename, doc.content]
          );
        }

        fs.unlinkSync(tmpFile);
        return true;
      } finally {
        client.release();
      }
    }
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req }) => ({
    headers: req.headers,
    clientIp: req.ip
  })
});

const app = express();
server.applyMiddleware({ app });

app.listen(4000, () => {
  console.log(`GraphQL server running on port 4000`);
});

module.exports = { app, resolvers };
